new PluginReexport([
  {
    entries: ['actions'],
    template({ files }) {
      return files.map(({ name }) => `export * from './${name}';`).join('\n');
    },
    validateContent({ content, name }) {
      return content.includes(`export async function ${name}(`);
    },
  },
]),
